create table if not exists public.membership_plans (id uuid primary key default gen_random_uuid(),name text not null,slug text not null unique,billing_interval text not null check (billing_interval in ('monthly','yearly')),price numeric(12,2) not null default 0 check(price>=0),currency text not null default 'INR' check(currency='INR'),benefits jsonb not null default '[]'::jsonb,active boolean not null default true,sort_order integer not null default 0,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.memberships (id uuid primary key default gen_random_uuid(),user_id uuid not null references public.profiles(id) on delete cascade,plan_id uuid not null references public.membership_plans(id),status text not null default 'pending' check(status in ('pending','active','expired','cancelled')),starts_at timestamptz,ends_at timestamptz,auto_renew boolean not null default false,payment_status text not null default 'pending' check(payment_status in ('pending','paid','failed','refunded')),payment_reference text,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.membership_transactions (id uuid primary key default gen_random_uuid(),membership_id uuid not null references public.memberships(id) on delete cascade,user_id uuid not null references public.profiles(id) on delete cascade,transaction_type text not null check(transaction_type in ('purchase','renewal','refund','cancellation')),amount numeric(12,2) not null check(amount>=0),currency text not null default 'INR' check(currency='INR'),status text not null default 'pending' check(status in ('pending','paid','failed','refunded')),provider text,provider_reference text,metadata jsonb not null default '{}'::jsonb,created_at timestamptz not null default now());
create index if not exists membership_plans_active_idx on public.membership_plans(active,sort_order); create index if not exists memberships_user_idx on public.memberships(user_id,created_at desc); create index if not exists membership_transactions_user_idx on public.membership_transactions(user_id,created_at desc);
alter table public.membership_plans enable row level security; alter table public.memberships enable row level security; alter table public.membership_transactions enable row level security;
drop policy if exists membership_plans_public_read on public.membership_plans; create policy membership_plans_public_read on public.membership_plans for select using(active=true);
drop policy if exists memberships_own_read on public.memberships; create policy memberships_own_read on public.memberships for select using(auth.uid()=user_id);
drop policy if exists membership_transactions_own_read on public.membership_transactions; create policy membership_transactions_own_read on public.membership_transactions for select using(auth.uid()=user_id);
revoke all on public.membership_plans from anon,authenticated; revoke all on public.memberships from anon,authenticated; revoke all on public.membership_transactions from anon,authenticated; grant select on public.membership_plans to anon,authenticated; grant select on public.memberships to authenticated; grant select on public.membership_transactions to authenticated;
create or replace function public.get_membership_plans() returns setof public.membership_plans language sql security invoker set search_path=public as $$ select * from public.membership_plans where active=true order by sort_order,price,name; $$; revoke all on function public.get_membership_plans() from public; grant execute on function public.get_membership_plans() to anon,authenticated;
create or replace function public.get_my_membership() returns jsonb language sql security invoker set search_path=public as $$ select coalesce((select jsonb_build_object('membership',to_jsonb(m),'plan',to_jsonb(p)) from public.memberships m join public.membership_plans p on p.id=m.plan_id where m.user_id=auth.uid() order by case when m.status='active' then 0 when m.status='pending' then 1 else 2 end,m.created_at desc limit 1),'{}'::jsonb); $$; revoke all on function public.get_my_membership() from public; grant execute on function public.get_my_membership() to authenticated;
create or replace function public.get_membership_history() returns setof public.membership_transactions language sql security invoker set search_path=public as $$ select * from public.membership_transactions where user_id=auth.uid() order by created_at desc; $$; revoke all on function public.get_membership_history() from public; grant execute on function public.get_membership_history() to authenticated;
create or replace function public.start_membership_purchase(p_plan_id uuid) returns jsonb language plpgsql security invoker set search_path=public as $$ declare v_user uuid:=auth.uid(); v_plan public.membership_plans; v_membership public.memberships; v_tx public.membership_transactions; begin if v_user is null then raise exception 'Authentication required'; end if; select * into v_plan from public.membership_plans where id=p_plan_id and active=true limit 1; if not found then raise exception 'Membership plan is unavailable'; end if; if exists(select 1 from public.memberships where user_id=v_user and status='active' and ends_at>now()) then raise exception 'An active membership already exists'; end if; insert into public.memberships(user_id,plan_id,status,payment_status) values(v_user,v_plan.id,'pending','pending') returning * into v_membership; insert into public.membership_transactions(membership_id,user_id,transaction_type,amount,currency,status,metadata) values(v_membership.id,v_user,'purchase',v_plan.price,v_plan.currency,'pending',jsonb_build_object('billing_interval',v_plan.billing_interval,'plan_slug',v_plan.slug)) returning * into v_tx; return jsonb_build_object('membership',to_jsonb(v_membership),'transaction',to_jsonb(v_tx),'payment_required',(v_plan.price>0)); end; $$; revoke all on function public.start_membership_purchase(uuid) from public; grant execute on function public.start_membership_purchase(uuid) to authenticated;